from pathlib import Path

def apply_medaglia(root):
 d=Path(root)/'dist';s=(d/'documenti.html').read_text();start=s.index('<main id="contenuto">');end=s.index('</main>',start)+7
 body='''<main id="contenuto"><div class="page-heading"><p class="eyebrow">DOCUMENTI · ONORIFICENZE</p><h1>Giovanni Martinelli · Medaglia d’argento al valor militare</h1><p>Meletta Davanti · 17 novembre 1917</p><p><a href="documenti.html">← Torna ai Documenti</a></p></div><article class="page-content"><img src="assets/medaglia-giovanni/medaglia.svg" alt="Icona illustrativa della medaglia d’argento, non riproduzione della decorazione originale" style="display:block;width:240px;height:auto;margin:0 auto 24px"><p>Giovanni Martinelli, da Monopoli (Bari), capitano del 129° reggimento fanteria. L’onorificenza è indicata come medaglia d’argento al valor militare dalla famiglia che ha fornito il ritaglio.</p><h2>La motivazione</h2><blockquote>«Nella occupazione di importanti posizioni seppe condurre con slancio e ardimento il proprio reparto. Per un’intera giornata lo tenne saldo sotto il violento fuoco di fucileria nemica, mirabile esempio di fermezza e coraggio. — Meletta Davanti, 17 novembre 1917».</blockquote><h2>Il documento originale</h2><p>Tocca l’immagine per ingrandirla e leggere il testo alla risoluzione disponibile.</p><a href="assets/medaglia-giovanni/motivazione.png" target="_blank" rel="noopener"><img src="assets/medaglia-giovanni/motivazione.png" alt="Ritaglio con la motivazione della decorazione di Giovanni Martinelli per Meletta Davanti, 17 novembre 1917" style="width:100%;height:auto;max-height:none;object-fit:contain"></a><p><a href="assets/medaglia-giovanni/motivazione.png" download>Scarica il ritaglio</a></p><h2>Fonte e criteri di trascrizione</h2><p>Riproduzione fornita dall’archivio familiare il 15 novembre 2026. Il ritaglio non mostra il titolo della pubblicazione, la data del provvedimento né l’intestazione della classe di medaglia: questi riferimenti restano da integrare. Il 17 novembre 1917 è la data dell’azione, non necessariamente quella del conferimento.</p><p>La trascrizione riunisce le parole spezzate a fine riga. La sigla «(M. M.)» dopo il reparto è conservata nell’immagine e non viene interpretata. L’icona è illustrativa.</p><p><a href="diario-di-guerra.html">Leggi il diario di guerra e il contesto delle Melette</a> · <a href="genealogia.html">Consulta la genealogia</a></p></article></main>'''
 s=s[:start]+body+s[end:];s=s.replace('<title>Documenti · Famiglia Martinelli</title>','<title>Giovanni Martinelli · Medaglia d’argento al valor militare</title>');(d/'medaglia-argento-giovanni.html').write_text(s)
